using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using SplifyWin;
namespace Mcrf.Wpf {public sealed partial class MainWindow {
 UIElement VkCallRows(TextBox source,int maximum=0){
  var panel=new StackPanel();var input=new TextBox{Name="vkCallPaste",AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=48,MaxHeight=90,ToolTip="Вставьте ссылки или хеши звонков"};panel.Children.Add(input);
  var feedback=Text("",11);feedback.Visibility=Visibility.Collapsed;panel.Children.Add(feedback);var rows=new StackPanel{Name="vkCallRows"};panel.Children.Add(new ScrollViewer{Content=rows,MaxHeight=220,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});
  Func<string,string[]> parse=text=>System.Text.RegularExpressions.Regex.Split(text??"",@"[\s,;]+").Where(x=>!String.IsNullOrWhiteSpace(x)).Select(VkCalls.CallHash).Distinct(StringComparer.Ordinal).Select(x=>"https://vk.ru/call/join/"+x).ToArray();
  Action render=null;bool changing=false;render=()=>{if(changing)return;string[] values;try{values=parse(source.Text);}catch(Exception ex){feedback.Text=FailureExplanations.UserMessage(JournalStyle.Redact(ex.Message));feedback.Visibility=Visibility.Visible;return;}changing=true;try{source.Text=String.Join("\n",values);rows.Children.Clear();for(int i=0;i<values.Length;i++){string value=values[i];var row=new Grid{Name="vkCallRow",MinHeight=40,Margin=new Thickness(4)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(36)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(36)});row.Children.Add(new TextBlock{Text=(i+1)+". "+value,TextTrimming=TextTrimming.CharacterEllipsis,VerticalAlignment=VerticalAlignment.Center,ToolTip=value,Foreground=Brush(CompactPrimary)});var copy=IconButton("copy","Копировать звонок",()=>CopyText(value));copy.MinWidth=0;copy.Width=32;copy.Height=32;copy.MinHeight=32;copy.Padding=new Thickness(6);copy.Margin=new Thickness(2,0,0,0);Grid.SetColumn(copy,1);row.Children.Add(copy);var remove=Button("×",()=>{source.Text=String.Join("\n",parse(source.Text).Where(x=>x!=value));});remove.ToolTip="Удалить звонок";remove.MinWidth=0;remove.Width=32;remove.Height=32;remove.MinHeight=32;remove.Padding=new Thickness(0);remove.Margin=new Thickness(2,0,0,0);Grid.SetColumn(remove,2);row.Children.Add(remove);rows.Children.Add(new Border{Name="vkCallCard",Child=row,Background=Brush(CompactElevated),BorderBrush=Brush(CompactOutline),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Margin=new Thickness(0,0,0,8)});}}finally{changing=false;}};
  source.TextChanged+=(s,e)=>render();Action<string> append=text=>{try{var incoming=parse(text);var existing=parse(source.Text);var merged=existing.Concat(incoming).Distinct(StringComparer.Ordinal).ToArray();if(maximum>0&&merged.Length>maximum)throw new FormatException("Не больше "+maximum+" звонков.");source.Text=String.Join("\n",merged);input.Clear();feedback.Text="Звонков: "+parse(source.Text).Length+" · повторы удалены";feedback.Visibility=Visibility.Visible;}catch(Exception ex){feedback.Text=FailureExplanations.UserMessage(JournalStyle.Redact(ex.Message));}};DataObject.AddPastingHandler(input,(s,e)=>{string format=e.DataObject.GetDataPresent(DataFormats.UnicodeText)?DataFormats.UnicodeText:DataFormats.Text;if(!e.DataObject.GetDataPresent(format))return;var text=e.DataObject.GetData(format) as string;if(text==null)return;e.CancelCommand();input.Text=text;append(text);});input.PreviewKeyDown+=(s,e)=>{if(e.Key==System.Windows.Input.Key.Enter){e.Handled=true;append(input.Text);}};render();return panel;
 }
}}
